#include "Analyzer.h"
#include <thread>
static void testAnalyzer(const File& root,Assets& assets){
    auto queue=std::make_unique<AnalyzerCapture>();auto token=queue->selectSource(7);expect(AnalyzerCapture::source(token)==7,"analysis selection atomically identifies a source and generation");for(unsigned i=0;i<AnalyzerCapture::capacity+123;++i)queue->push((float)i,-(float)i,48000,token);expect(queue->dropped()==123,"analysis queue has a fixed bound and counts dropped frames without overwriting unread data");AnalyzerCapture::Frame frame;unsigned count=0;bool coherent=true;while(queue->pop(frame)){coherent&=frame.left==count&&frame.right==-(float)count&&frame.rate==48000&&frame.token==token;++count;}expect(coherent&&count==AnalyzerCapture::capacity,"bounded analysis FIFO retains ordered coherent stereo metadata");auto newer=queue->selectSource(-1);auto newest=queue->selectSource(7);expect(newer!=token&&newest!=token&&AnalyzerCapture::source(newer)==-1,"returning to a source uses a fresh generation so old measurements cannot leak");queue->push(1,2,48000,token);queue->discard();expect(!queue->pop(frame),"UI discard clears old queued analysis without touching audio state");
    queue=std::make_unique<AnalyzerCapture>();std::atomic<bool> done{false};uint64_t consumed=0;float previous=-1;bool ordered=true;std::thread producer([&]{for(int i=0;i<100000;++i)queue->push((float)i,-(float)i,44100,55);done.store(true,std::memory_order_release);});auto consume=[&]{while(queue->pop(frame)){ordered&=frame.left>previous&&frame.right==-frame.left&&frame.rate==44100&&frame.token==55;previous=frame.left;++consumed;}};while(!done.load(std::memory_order_acquire)){consume();std::this_thread::yield();}producer.join();consume();expect(ordered&&consumed+queue->dropped()==100000,"concurrent audio/UI FIFO stress has coherent frames and accounts for every drop");
    AnalyzerModel model;for(double rate:{8000.,44100.,48000.,96000.,192000.}){model.reset(rate);model.beginBatch();for(int i=0;i<AnalyzerModel::size*3;++i){float value=(float)(.4*std::sin(2*MathConstants<double>::pi*40*i/AnalyzerModel::size));model.feed(value,value,rate);}model.finishBatch();int maximum=1;for(int i=2;i<AnalyzerModel::bins;++i)if(model.magnitude(i)>model.magnitude(maximum))maximum=i;expect(maximum==40&&std::abs(model.frequency(maximum)-40*rate/AnalyzerModel::size)<.000001,"FFT peak frequency follows device sample rate across supported rates");expect(std::abs(model.magnitude(40)-.4f)<.00001f&&std::abs(AnalyzerModel::decibels(model.magnitude(40))-20*std::log10(.4))<.001,"Hann coherent gain is calibrated to dBFS sine amplitude");}
    for(bool antiPhase:{false,true}){model.reset();model.beginBatch();for(int i=0;i<144000;++i){float l=(float)(.5*std::sin(2*MathConstants<double>::pi*32*i/AnalyzerModel::size));model.feed(l,antiPhase?-l:l,48000);}model.finishBatch();expect(std::abs(model.rms(0)-.5/std::sqrt(2.))<.0003&&std::abs(model.peakHold(0)-.5f)<.00001,"RMS and held sample peak have their correct distinct sine calibrations");expect(model.correlationReady()&&std::abs(model.correlation()-(antiPhase?-1:1))<.00001,"stereo correlation identifies matching and inverted channels");expect(std::abs(model.magnitude(32)-.5f)<.00001,"power-averaged stereo spectrum does not cancel anti-phase audio");}
    model.reset();model.beginBatch();for(int i=0;i<144000;++i){double phase=2*MathConstants<double>::pi*32*i/AnalyzerModel::size;model.feed((float)(.5*std::sin(phase)),(float)(.5*std::cos(phase)),48000);}model.finishBatch();expect(model.correlationReady()&&std::abs(model.correlation())<.002,"quadrature channels have near-zero correlation");
    model.reset();model.beginBatch();for(int i=0;i<AnalyzerModel::size*3;++i){float l=(float)(.5*std::sin(2*MathConstants<double>::pi*32*i/AnalyzerModel::size));model.feed(l,0,48000);}model.finishBatch();expect(!model.correlationReady()&&std::abs(model.magnitude(32)-.5/std::sqrt(2.))<.00001,"single-channel spectrum uses stereo power normalization and correlation is unavailable");
    for(bool nyquist:{false,true}){model.reset();model.beginBatch();for(int i=0;i<AnalyzerModel::size*3;++i){float v=nyquist&&i%2?-.25f:.25f;model.feed(v,v,48000);}model.finishBatch();expect(std::abs(model.magnitude(nyquist?AnalyzerModel::size/2:0)-.25f)<.00001,"DC and Nyquist bins are not doubled by sine-amplitude normalization");}
    model.reset();model.beginBatch();model.feed(1.2f,-1.f,48000);model.feed(.2f,-.5f,48000);model.finishBatch();expect(model.clips(0)==1&&model.clips(1)==1&&model.peakHold(0)==1.2f,"full-scale counters and held peaks retain brief over-level samples");model.beginBatch();for(int i=0;i<48000;++i)model.feed(0,0,48000);model.finishBatch();expect(model.peak(0)<.3f&&model.peakHold(0)==1.2f&&model.clips(0)==1,"current peak decays while peak hold and clip counters remain until reset");model.reset();expect(model.samples()==0&&!model.spectrumReady()&&model.peakHold(0)==0&&model.clips(0)==0&&!model.correlationReady(),"reset clears all measurements and invalidates the FFT window");
    model.beginBatch();model.feed(std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN(),48000);model.feed(1e30f,0,48000);for(int i=0;i<AnalyzerModel::size;++i)model.feed(0,0,48000);model.finishBatch();expect(model.invalidSamples()==3&&std::isfinite(model.rms(0))&&model.magnitude(20)==0,"invalid and absurd analysis inputs are counted without poisoning meters or FFT");model.feed(0,0,44100);expect(model.sampleRate()==44100&&model.samples()==1&&!model.spectrumReady(),"device rate changes begin a fresh calibrated measurement window");
    AnalyzerModel whole,chunks;whole.beginBatch();for(int i=0;i<24000;++i){float l=.3f*std::sin(i*.1f),r=-l;whole.feed(l,r,48000);if(i%127==0){chunks.finishBatch();chunks.beginBatch();}chunks.feed(l,r,48000);}whole.finishBatch();chunks.finishBatch();bool same=whole.samples()==chunks.samples()&&whole.rms(0)==chunks.rms(0)&&whole.correlation()==chunks.correlation()&&whole.peakHold(0)==chunks.peakHold(0);for(int i=0;i<AnalyzerModel::bins;++i)same&=whole.magnitude(i)==chunks.magnitude(i);expect(same,"meter calibration and the final FFT are independent of UI batch sizes");
    auto song=emptyProject();song.bpm=120;song.loop=false;song.patterns[0].lanes[7]={{0,1,60,.8f}};auto observed=makeEngine(song,assets,root),reference=makeEngine(song,assets,root);auto masterToken=observed->analyzer.selectSource(-1);observed->analyzer.enabled.store(true);AudioBuffer<float> a(2,512),b(2,512);bool exact=true,matching=true;uint64_t captured=0;
    for(int block=0;block<50;++block){observed->render(a.getWritePointer(0),a.getWritePointer(1),512);reference->render(b.getWritePointer(0),b.getWritePointer(1),512);for(int i=0;i<512;++i)exact&=a.getSample(0,i)==b.getSample(0,i)&&a.getSample(1,i)==b.getSample(1,i);int i=0;while(observed->analyzer.pop(frame)){matching&=i<512&&frame.token==masterToken&&frame.rate==48000&&frame.left==a.getSample(0,i)&&frame.right==a.getSample(1,i);++i;++captured;}}
    expect(exact&&matching&&captured==50*512&&observed->analyzer.dropped()==0,"Master tap exactly matches output and enabling analysis never changes audio");
    observed=makeEngine(song,assets,root);reference=makeEngine(song,assets,root);observed->analyzer.enabled.store(true);AudioBuffer<float> largeA(2,24000),largeB(2,24000);observed->render(largeA.getWritePointer(0),largeA.getWritePointer(1),24000);reference->render(largeB.getWritePointer(0),largeB.getWritePointer(1),24000);exact=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)exact&=largeA.getSample(ch,i)==largeB.getSample(ch,i);expect(exact&&observed->analyzer.dropped()==24000-AnalyzerCapture::capacity,"analysis overload drops only analysis frames while audio stays bit-exact");
    song.tracks[7].pan=-1;song.tracks[7].send=0;song.tracks[7].mixer.output=5;song.tracks[5].isBus=true;song.tracks[5].mute=true;auto channel=makeEngine(song,assets,root);channel->analyzer.selectSource(7);channel->analyzer.enabled.store(true);bool channelAudible=false,onlyLeft=true,masterSilent=true;for(int block=0;block<30;++block){channel->render(a.getWritePointer(0),a.getWritePointer(1),512);masterSilent&=a.getMagnitude(0,0,512)==0&&a.getMagnitude(1,0,512)==0;while(channel->analyzer.pop(frame)){channelAudible|=std::abs(frame.left)>.001;onlyLeft&=frame.right==0;}}expect(channelAudible&&onlyLeft&&masterSilent,"channel analysis is post-pan/fader and remains independent of a muted downstream bus");
    song.tracks[5].mute=false;song.tracks[5].cutoff=20000;song.tracks[5].volume=1;auto bus=makeEngine(song,assets,root);bus->analyzer.selectSource(5);bus->analyzer.enabled.store(true);matching=true;for(int block=0;block<30;++block){bus->render(a.getWritePointer(0),a.getWritePointer(1),512);int i=0;while(bus->analyzer.pop(frame)){matching&=std::abs(a.getSample(0,i)-std::tanh(frame.left*song.master))<.000001f&&std::abs(a.getSample(1,i)-std::tanh(frame.right*song.master))<.000001f;++i;}}expect(matching,"bus tap is post-effects/fader and precedes the master gain/limiting stage");
    auto empty=emptyProject();auto preview=makeEngine(empty,assets,root);preview->stop();Sample sample;sample.sampleRate=48000;sample.audio.setSize(2,5000);for(int i=0;i<5000;++i){sample.audio.setSample(0,i,.25f);sample.audio.setSample(1,i,-.1f);}preview->preview(&sample);preview->analyzer.enabled.store(true);preview->analyzer.selectSource(-1);preview->render(a.getWritePointer(0),a.getWritePointer(1),512);matching=true;int i=0;while(preview->analyzer.pop(frame)){matching&=frame.left==a.getSample(0,i)&&frame.right==a.getSample(1,i);++i;}expect(matching&&a.getMagnitude(0,0,512)>.1f,"Master analyzer includes the real Browser preview signal");preview->analyzer.selectSource(7);preview->render(a.getWritePointer(0),a.getWritePointer(1),512);bool quiet=true;while(preview->analyzer.pop(frame))quiet&=frame.left==0&&frame.right==0;expect(quiet&&a.getMagnitude(0,0,512)>.1f,"channel analysis excludes the independent Browser preview");
}
